function createClickQueue( stream: StreamWriter, spoolPath: string, log: (message: string) => void = console.error, ) { let spooled: ClickMessage[] = []; let draining: Promise<void> | undefined; metrics.gauge("click_spool_size", () => spooled.length); const write = async (message: ClickMessage) => { await stream.xadd(keys.clicksStream, "*", ...encodeClickMessage(message)); }; const spool = async (message: ClickMessage) => { spooled.push(message); metrics.inc("click_spooled_total"); try { await appendFile(spoolPath, `${JSON.stringify(message)}
`); } catch (error) { log(`click spool write failed: ${String(error)}`); } }; const persist = async () => { if (!spooled.length) { await unlink(spoolPath).catch(() => undefined); return; } const temporary = `${spoolPath}.tmp`; await Bun.write( temporary, spooled.map((message) => JSON.stringify(message)).join("
") + "
", ); await rename(temporary, spoolPath); }; const drain = () => { draining ??= (async () => { try { while (spooled.length) { const next = spooled[0]; if (!next) break; await write(next); spooled.shift(); metrics.inc("click_replayed_total"); } } catch { /* Redis is still unreachable; the next drain retries. */ } finally { await persist().catch((error: unknown) => log(`click spool persist failed: ${String(error)}`), ); draining = undefined; } })(); return draining; }; const enqueue: Enqueue = (message) => { metrics.inc("click_enqueued_total"); if (spooled.length) { void spool(message); return; } write(message).catch(() => spool(message)); }; return { enqueue, drain, get spooled() { return spooled.length; }, async load() { const file = Bun.file(spoolPath); if (!(await file.exists())) return; spooled = (await file.text()) .split("
") .filter(Boolean) .flatMap((line) => { try { const parsed = clickMessageSchema.safeParse(JSON.parse(line)); return parsed.success ? [parsed.data] : []; } catch { return []; } }); }, }; }

function envExample(): string { const sections = { web: webEnv, redirect: redirectEnv, api: apiEnv, worker: workerEnv, "legacy infrastructure": legacyInfraEnv, }; const seen = new Set<string>(); return Object.entries(sections) .map(([app, schema]) => { const entries = Object.entries(schema.shape).flatMap(([key, field]) => { if (seen.has(key)) return []; seen.add(key); const meta = field.meta(); return [ `# ${meta?.description ?? key}
${key}=${String(meta?.example ?? "")}
`, ]; }); return `# ${app} (also uses shared variables above)
${entries.join("
")}`; }) .join("
"); }
